import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { patientApi } from '../../api/patientApi';
import Card from '../../components/Card';
import ErrorBox from '../../components/ErrorBox';
import Loader from '../../components/Loader';

const AllDoctors = () => {
  const navigate = useNavigate();
  const [doctors, setDoctors] = useState([]);
  const [selectedDoctor, setSelectedDoctor] = useState(null);
  const [selectedDate, setSelectedDate] = useState('');
  const [slots, setSlots] = useState([]);
  const [formData, setFormData] = useState({
    reason: '',
    notes: ''
  });
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [loading, setLoading] = useState(false);
  const [loadingSlots, setLoadingSlots] = useState(false);
  const [showBookingForm, setShowBookingForm] = useState(false);

  useEffect(() => {
    const fetchDoctors = async () => {
      try {
        const response = await patientApi.getAllDoctors();
        if (response.success) {
          setDoctors(response.doctors);
        }
      } catch (err) {
        setError(err.response?.data?.message || 'Failed to fetch doctors');
      }
    };
    fetchDoctors();
  }, []);

  useEffect(() => {
    if (selectedDoctor && selectedDate && showBookingForm) {
      fetchSlots();
    } else {
      setSlots([]);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedDoctor, selectedDate, showBookingForm]);

  const fetchSlots = async () => {
    setLoadingSlots(true);
    setError('');
    try {
      const response = await patientApi.getAvailableSlots(selectedDoctor._id, selectedDate);
      if (response.success) {
        setSlots(response.slots || []);
        if (!response.slots || response.slots.length === 0) {
          setError('No available slots for this date. Please try a different date.');
        }
      }
    } catch (err) {
      const errorMsg = err.response?.data?.message || err.message || 'Failed to fetch slots';
      setError(errorMsg);
    } finally {
      setLoadingSlots(false);
    }
  };

  const [selectedSlot, setSelectedSlot] = useState(null);

  const handleBookAppointment = (doctor) => {
    setSelectedDoctor(doctor);
    setShowBookingForm(true);
    setError('');
    setSuccess('');
    setSelectedSlot(null);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!selectedSlot) {
      setError('Please select a time slot');
      return;
    }

    setError('');
    setLoading(true);

    try {
      const response = await patientApi.bookAppointment({
        doctorId: selectedDoctor._id,
        appointmentDate: selectedDate,
        slotTime: selectedSlot,
        reason: formData.reason,
        notes: formData.notes
      });

      if (response.success) {
        setSuccess('Appointment booked successfully!');
        setTimeout(() => {
          setShowBookingForm(false);
          setSelectedDoctor(null);
          setSelectedDate('');
          setSelectedSlot(null);
          setFormData({ reason: '', notes: '' });
          navigate('/patient/appointments');
        }, 2000);
      } else {
        setError(response.message || 'Failed to book appointment');
      }
    } catch (err) {
      const errorMessage = err.response?.data?.message || err.message || 'Failed to book appointment';
      setError(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  if (showBookingForm) {
    return (
      <div className="p-6 max-w-4xl mx-auto">
        <button
          onClick={() => {
            setShowBookingForm(false);
            setSelectedDoctor(null);
            setSelectedDate('');
            setSelectedSlot(null);
            setError('');
          }}
          className="mb-6 text-blue-600 hover:text-blue-700 flex items-center gap-2 font-medium"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
          </svg>
          Back to Doctors
        </button>

        <Card className="border-2 border-blue-200">
          <div className="mb-6">
            <h2 className="text-3xl font-bold text-gray-800 mb-2">Book Appointment</h2>
            <div className="flex items-center gap-3 p-4 bg-blue-50 rounded-lg">
              <div className="w-16 h-16 bg-blue-600 rounded-full flex items-center justify-center">
                <span className="text-white font-bold text-xl">
                  Dr. {selectedDoctor?.user?.name?.charAt(0) || 'D'}
                </span>
              </div>
              <div>
                <h3 className="text-xl font-bold text-gray-800">Dr. {selectedDoctor?.user?.name || 'N/A'}</h3>
                <p className="text-gray-600">{selectedDoctor?.specialization || 'N/A'}</p>
                <p className="text-sm text-gray-500">{selectedDoctor?.qualification || 'N/A'}</p>
              </div>
            </div>
          </div>

          {error && <ErrorBox message={error} onClose={() => setError('')} />}
          {success && (
            <div className="bg-green-100 border border-green-400 text-green-700 px-4 py-3 rounded-lg mb-4">
              {success}
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-6">
            <div>
              <label className="block text-gray-700 text-sm font-semibold mb-2">
                Select Date
              </label>
              <input
                type="date"
                value={selectedDate}
                onChange={(e) => setSelectedDate(e.target.value)}
                className="input"
                required
              />
            </div>

            {selectedDate && (
              <div>
                <label className="block text-gray-700 text-sm font-semibold mb-2">
                  Available Time Slots
                </label>
                {loadingSlots ? (
                  <div className="text-center py-8">
                    <Loader />
                  </div>
                ) : slots.length > 0 ? (
                  <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                    {slots.map((slot, index) => (
                      <button
                        key={index}
                        type="button"
                        onClick={() => setSelectedSlot(slot)}
                        className={`
                          p-4 rounded-lg border-2 transition-all duration-200 font-medium
                          ${selectedSlot?.startTime === slot.startTime
                            ? 'border-blue-600 bg-blue-50 text-blue-700 shadow-md'
                            : 'border-gray-200 hover:border-blue-300 hover:bg-blue-50 text-gray-700'
                          }
                        `}
                      >
                        {slot.startTime} - {slot.endTime}
                      </button>
                    ))}
                  </div>
                ) : (
                  <p className="text-gray-600 text-center py-4">No slots available for this date</p>
                )}
              </div>
            )}

            <div>
              <label className="block text-gray-700 text-sm font-semibold mb-2">
                Reason for Visit *
              </label>
              <textarea
                value={formData.reason}
                onChange={(e) => setFormData({ ...formData, reason: e.target.value })}
                className="input"
                rows="3"
                placeholder="Describe your symptoms or reason for appointment"
                required
              />
            </div>

            <div>
              <label className="block text-gray-700 text-sm font-semibold mb-2">
                Additional Notes (Optional)
              </label>
              <textarea
                value={formData.notes}
                onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                className="input"
                rows="2"
                placeholder="Any additional information"
              />
            </div>

            <button
              type="submit"
              disabled={loading || !selectedSlot}
              className="w-full btn btn-secondary py-3 text-lg font-semibold disabled:opacity-50"
            >
              {loading ? 'Booking...' : 'Book Appointment'}
            </button>
          </form>
        </Card>
      </div>
    );
  }

  return (
    <div className="p-6 max-w-7xl mx-auto">
      <div className="mb-8 fade-in">
        <h1 className="text-4xl font-bold text-gray-800 mb-2">Find a Doctor</h1>
        <p className="text-gray-600 text-lg">Browse available doctors and book your appointment</p>
      </div>

      {error && <ErrorBox message={error} onClose={() => setError('')} />}

      <div className="mb-6">
        <Card className="bg-gradient-to-r from-blue-50 to-indigo-50 border-blue-200">
          <div className="flex items-start gap-4">
            <div className="bg-blue-600 p-3 rounded-lg">
              <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
            </div>
            <div>
              <h3 className="font-semibold text-gray-800 mb-2">Available Time Slots</h3>
              <p className="text-sm text-gray-700 mb-2">
                <strong>Monday - Saturday:</strong> 6 slots per day
              </p>
              <ul className="text-sm text-gray-600 space-y-1">
                <li>• Morning: 09:00-10:00, 10:00-11:00, 11:00-12:00</li>
                <li>• Afternoon: 14:00-15:00, 15:00-16:00, 16:00-17:00</li>
              </ul>
              <p className="text-sm text-blue-700 font-medium mt-2">
                💡 You can book appointments for any date - no restrictions!
              </p>
            </div>
          </div>
        </Card>
      </div>

      {doctors.length > 0 ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {doctors.map((doctor) => (
            <Card key={doctor._id} hover className="border-2 border-gray-200 hover:border-blue-300">
              <div className="text-center mb-4">
                <div className="w-20 h-20 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-full flex items-center justify-center mx-auto mb-4">
                  <span className="text-white font-bold text-2xl">
                    Dr. {doctor.user?.name?.charAt(0) || 'D'}
                  </span>
                </div>
                <h3 className="text-xl font-bold text-gray-800 mb-1">
                  Dr. {doctor.user?.name || 'N/A'}
                </h3>
                <p className="text-blue-600 font-semibold mb-1">{doctor.specialization || 'N/A'}</p>
                <p className="text-sm text-gray-600">{doctor.qualification || 'N/A'}</p>
              </div>

              <div className="space-y-2 mb-6 text-sm">
                <div className="flex items-center gap-2 text-gray-700">
                  <svg className="w-4 h-4 text-gray-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 13.255A23.931 23.931 0 0112 15c-3.183 0-6.22-.62-9-1.745M16 6V4a2 2 0 00-2-2h-4a2 2 0 00-2 2v2m4 6h.01M5 20h14a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" />
                  </svg>
                  {doctor.experience} years experience
                </div>
                <div className="flex items-center gap-2 text-gray-700">
                  <svg className="w-4 h-4 text-gray-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                  </svg>
                  ₹{doctor.consultationFee || 'N/A'} consultation fee
                </div>
                {doctor.bio && (
                  <p className="text-gray-600 text-xs mt-3 line-clamp-2">{doctor.bio}</p>
                )}
              </div>

              <button
                onClick={() => handleBookAppointment(doctor)}
                className="w-full btn btn-primary py-3 font-semibold"
              >
                Book Appointment
              </button>
            </Card>
          ))}
        </div>
      ) : (
        <Card>
          <div className="text-center py-12">
            <svg className="w-16 h-16 text-gray-400 mx-auto mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
            </svg>
            <p className="text-gray-600 text-lg">No doctors available</p>
          </div>
        </Card>
      )}
    </div>
  );
};

export default AllDoctors;
